def newton_seguro(f, df, x0, tol=1e-10, max_iter=50):
    x = x0
    for k in range(max_iter):
        try:
            x_nuevo = x - f(x) / df(x)
        except ZeroDivisionError:
            print(f"Derivada nula en iteración {k}. Deteniendo.")
            return None, k
        if abs(x_nuevo - x) < tol:
            return x_nuevo, k
        x = x_nuevo
    return x, max_iter

