class DivergenciaError(Exception):
    """El método se aleja en vez de converger."""
    pass

def iterar(x0, pasos=10):
    x = x0
    for k in range(pasos):
        x = x**2 + 1
        if abs(x) > 1e6:
            raise DivergenciaError(f"Diverge en iter {k}: |x| = {abs(x):.2e}")
    return x

try:
    resultado = iterar(2.0)
    print(f"Resultado: {resultado}")
except DivergenciaError as e:
    print(f"Error propio: {e}")

