def biseccion(f, a, b, tol=1e-8, max_iter=100):
    if f(a) * f(b) >= 0:
        raise ValueError("Bolzano no se cumple: f(a) y f(b) deben tener signos opuestos")

    for k in range(max_iter):
        c = (a + b) / 2
        if abs(f(c)) < tol:
            return c, k
        if f(a) * f(c) < 0:
            b = c
        else:
            a = c

    raise RuntimeError(f"No convergió en {max_iter} iteraciones")

f = lambda x: x**3 - x - 2

# Caso válido
