class MetodoNumericoError(Exception):
    """Base para errores de métodos numéricos."""
    pass

class NoConvergenciaError(MetodoNumericoError):
    """El método no convergió."""
    pass

class DerivadaNulaError(MetodoNumericoError):
    """La derivada se anuló."""
    pass

def newton(f, df, x0, tol=1e-10, max_iter=50):
    x = x0
    for k in range(max_iter):
        if abs(df(x)) < 1e-14:
            raise DerivadaNulaError(f"f'(x) = 0 en x = {x:.6f}")
        x_nuevo = x - f(x) / df(x)
        if abs(x_nuevo - x) < tol:
            return x_nuevo, k
        x = x_nuevo
    raise NoConvergenciaError(f"No convergió en {max_iter} iteraciones")

try:
    newton(lambda x: x**2, lambda x: 2*x, 0)
except MetodoNumericoError as e:
    print(f"Error (cualquier subclase): {e}")

class NoConvergenciaError(Exception):
    def __init__(self, iteraciones, error_final):
        self.iteraciones = iteraciones
        self.error_final = error_final
        mensaje = f"No convergió en {iteraciones} iteraciones. Error final: {error_final:.3e}"
        super().__init__(mensaje)

try:
    raise NoConvergenciaError(100, 1e-3)
except NoConvergenciaError as e:
    print(f"Mensaje: {e}")
    print(f"Iteraciones: {e.iteraciones}")
    print(f"Error final: {e.error_final}")

