def promedio(numeros):
    print(f"DEBUG: numeros = {numeros}")
    print(f"DEBUG: len = {len(numeros)}")

    suma = 0
    for n in numeros:
        print(f"DEBUG: sumando {n}, suma actual = {suma}")
        suma += n

    print(f"DEBUG: suma final = {suma}")
    return suma / len(numeros)

print("Resultado:", promedio([10, 20, 30]))

