# Excepción: cuando el usuario pasa datos inválidos
def biseccion(f, a, b, tol=1e-8):
    if f(a) * f(b) >= 0:
        raise ValueError("Bolzano no se cumple")
    for _ in range(100):
        c = (a + b) / 2
        if abs(f(c)) < tol:
            return c
        if f(a) * f(c) < 0:
            b = c
        else:
            a = c
    raise RuntimeError("No convergió")

# if/else: para decisiones dentro del algoritmo
def signo(x):
    return -1 if x < 0 else (1 if x > 0 else 0)

# try/except: para capturar errores del usuario
try:
    raiz = biseccion(lambda x: x**2, 1, 2)
